<?php
require "config.php";require "funciones_correo.php";
$ids=array_values(array_unique(array_filter(array_map('intval',$_POST['ids']??[]))));if(!$ids)die('No seleccionó participantes. <a href="listado.php">Volver</a>');
$sent=0;$failed=0;$results=[];
foreach($ids as $id){$s=$conexion->prepare("SELECT * FROM certificados WHERE id=?");$s->bind_param('i',$id);$s->execute();$r=$s->get_result();if(!$r||!$r->num_rows)continue;$c=$r->fetch_assoc();$name=$c['nombre'].' '.$c['apellido'];$path=__DIR__.'/certificados/'.basename($c['archivo']??'');if(empty($c['archivo'])||!is_file($path)){$failed++;$results[]=[$name,'No enviado: certificado pendiente'];continue;}[$ok,$msg]=enviarCertificado($c,$path);if($ok){$u=$conexion->prepare("UPDATE certificados SET fecha_envio=NOW(),estado_correo='ENVIADO' WHERE id=?");$u->bind_param('i',$id);$u->execute();$sent++;$results[]=[$name,'Envío aceptado por el servidor'];}else{$failed++;$results[]=[$name,$msg];}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Resultado de envío</title><style>body{font-family:Arial;background:#eee;padding:25px}.box{max-width:900px;margin:auto;background:#fff;padding:25px;border-radius:12px}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}a{display:inline-block;padding:12px;background:#9b741c;color:white;text-decoration:none;border-radius:6px}</style></head><body><div class="box"><h2>Resultado del envío masivo</h2><p>Envíos aceptados por el servidor: <b><?=$sent?></b></p><p>No enviados: <b><?=$failed?></b></p><table><tr><th>Participante</th><th>Resultado</th></tr><?php foreach($results as $v):?><tr><td><?=htmlspecialchars($v[0])?></td><td><?=htmlspecialchars($v[1])?></td></tr><?php endforeach;?></table><br><a href="listado.php">VOLVER AL LISTADO</a></div></body></html>